export const StarRating = ({ totalStars = 5, onRatingChange }) => {
  return (
    <div>
      {[...Array(totalStars)].map((_, index) => {
        const StarValue = index + 1;
        return <span key={StarValue}> * </span>;
      })}
    </div>
  );
};
